import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    # First line contains N and M
    first_line = data[0].split()
    N = int(first_line[0])
    M = int(first_line[1])

    # Next N lines are grid S
    S = []
    for i in range(1, 1 + N):
        S.append(data[i].strip())

    # Next M lines are grid T
    T = []
    for i in range(1 + N, 1 + N + M):
        T.append(data[i].strip())

    # Search for T in S
    # Try all possible top-left positions (a, b) where 1 <= a,b <= N-M+1
    # In 0-indexed: a from 0 to N-M, b from 0 to N-M
    found = False
    for a in range(N - M + 1):
        for b in range(N - M + 1):
            match = True
            for i in range(M):
                for j in range(M):
                    if S[a + i][b + j] != T[i][j]:
                        match = False
                        break
                if not match:
                    break
            if match:
                # Output 1-indexed coordinates
                print(a + 1, b + 1)
                found = True
                break
        if found:
            break

if __name__ == "__main__":
    main()
