class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total = 0
        n = len(nums)
        for i in range(n):
            # Check if index i-k exists and if nums[i] > nums[i-k]
            # Check if index i+k exists and if nums[i] > nums[i+k]
            # If neither exists, it's still good.
            # If only one exists, we need to check that one.
            # If both exist, we need to check both.

            good = True
            if i - k >= 0:
                if nums[i] <= nums[i - k]:
                    good = False
            if i + k < n:
                if nums[i] <= nums[i + k]:
                    good = False
            if good:
                total += nums[i]
        return total
